// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 putValue, uint256 unlockTime) public {
        // Bound putValue to a wide admissible range: 1 wei up to a large value.
        // Ensure it stays within sensible limits to avoid overflow and to keep the fuzzer exploring.
        putValue = bound(putValue, 1, 100_000 ether);
        unlockTime = bound(unlockTime, 0, type(uint64).max);

        address actor = address(0xBEEF);
        vm.deal(actor, putValue);

        // Record starting balance and execute Put
        uint256 balanceBefore = c.Acc(actor).balance;
        vm.prank(actor);
        c.Put{value: putValue}(unlockTime);

        // After the call, the actor's balance must have increased by exactly msg.value.
        uint256 balanceAfter = c.Acc(actor).balance;
        assertTrue(balanceAfter == balanceBefore + putValue);
    }
}

