// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTime, uint128 value, uint8 senderSeed) public {
        vm.assume(value > 0);
        address sender = address(uint160(senderSeed) + 1);
        vm.assume(sender != address(this));

        vm.deal(sender, value);

        // Helper: a contract that acts as a receiver that can collect later if needed.
        // The adversarial party is the caller; the difference doesn't require a failing external party,
        // so we just use a fresh EOA as the sender.
        // We deploy a minimal helper only if the difference depends on an adversarial external call.
        // Here the difference manifests purely through internal accounting, so we don't need one.

        vm.prank(sender);
        c.Put{value: value}(unlockTime);

        uint256 totalBalance;
        // We can't iterate over all addresses, but we can replicate the invariant
        // by computing the sum-of-Acc for the two known addresses: sender and this.
        // However, the invariant must hold for all addresses, which we can't compute without iterating.
        // Since the contract only has two holders (sender and this), that's acceptable for the fuzzer.
        totalBalance = c.Acc(sender).balance + c.Acc(address(this)).balance;

        // MinSum is initially 1 ether; the invariant: totalBalance + MinSum == address(c).balance
        // The bug won't add msg.value to sender's balance, so totalBalance will be lower than it should be,
        // violating the equality.
        assertEq(totalBalance + c.MinSum(), address(c).balance);
    }
}

