pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 amount3, uint256 unlockTime1, uint256 unlockTime2, uint256 unlockTime3, uint256 collectAmt) public {
        // restrict amounts to reasonable ranges
        amount1 = bound(amount1, 0, 100 ether);
        amount2 = bound(amount2, 0, 100 ether);
        amount3 = bound(amount3, 0, 100 ether);
        unlockTime1 = bound(unlockTime1, 0, type(uint64).max);
        unlockTime2 = bound(unlockTime2, 0, type(uint64).max);
        unlockTime3 = bound(unlockTime3, 0, type(uint64).max);
        collectAmt = bound(collectAmt, 0, 100 ether);

        // Ensure we never exceed balance in subsequent operations
        vm.assume(amount1 + amount2 + amount3 <= 100 ether);

        address caller = address(0xbeef);
        vm.deal(caller, amount1 + amount2 + amount3);

        // First Put
        vm.warp(1000);
        vm.prank(caller);
        c.Put{value: amount1}(unlockTime1);

        // Second Put
        vm.warp(2000);
        vm.prank(caller);
        c.Put{value: amount2}(unlockTime2);

        // Third Put
        vm.warp(3000);
        vm.prank(caller);
        c.Put{value: amount3}(unlockTime3);

        // Record balance after deposits
        uint256 balanceAfterDeposits = c.Acc(caller).balance;

        // Attempt a Collect - only if conditions allow; we track collected amount
        uint256 collected = 0;
        uint256 accUnlockTime = c.Acc(caller).unlockTime;
        if (balanceAfterDeposits >= c.MinSum() && balanceAfterDeposits >= collectAmt && block.timestamp > accUnlockTime && collectAmt > 0) {
            // Warp past unlock time if necessary
            if (block.timestamp <= accUnlockTime) {
                vm.warp(accUnlockTime + 1);
            }
            uint256 balBefore = address(caller).balance;
            vm.prank(caller);
            try c.Collect(collectAmt) {
                collected = collectAmt;
            } catch {}
        }

        // Total deposited by caller = amount1 + amount2 + amount3
        uint256 totalDeposited = amount1 + amount2 + amount3;
        // Current Acc[caller].balance after possible Collect
        uint256 currentBalance = c.Acc(caller).balance;
        // Invariant: currentBalance + collected == totalDeposited
        assertTrue(currentBalance + collected == totalDeposited);
    }
}

