pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 collectAmt) public {
        // Keep amounts within admissible wide range
        vm.assume(deposit1 > 0);
        vm.assume(deposit2 > 0);
        vm.assume(collectAmt > 0);
        vm.assume(deposit1 < 1000 ether);
        vm.assume(deposit2 < 1000 ether);
        vm.assume(collectAmt < 1000 ether);

        // Deploy a helper that fails on receive to test Collect with reverting external call
        Reverter reverter = new Reverter();

        // Addresses
        address alice = address(0x1000);
        address bob = address(0x2000);

        // Fund actors
        vm.deal(alice, 10000 ether);
        vm.deal(bob, 10000 ether);

        // Alice makes two deposits
        vm.prank(alice);
        c.Put{value: deposit1}(block.timestamp + 100);

        vm.prank(alice);
        c.Put{value: deposit2}(block.timestamp + 100);

        // Bob makes a deposit
        vm.prank(bob);
        c.Put{value: 1 ether}(block.timestamp + 100);

        // Advance time to allow Collect
        vm.warp(block.timestamp + 200);

        // Record contract balance before collects
        uint256 contractBalBefore = address(c).balance;

        // Alice attempts Collect to a contract that reverts (should fail, no balance change)
        vm.prank(alice);
        try c.Collect(collectAmt) {
            // Should not succeed if collectAmt too large or call reverts
        } catch {
            // Expected if external call fails
        }

        // Alice attempts a second Collect to a non-reverting address (this one should succeed if constraints met)
        // We use a simple call without specifying recipient; Collect sends to msg.sender, which is alice (EOA) -> always succeeds
        // But we need to test Collect that actually succeeds: do a valid Collect from bob
        uint256 bobBal = c.Acc(bob).balance;
        vm.prank(bob);
        try c.Collect(bobBal) {
            // Should succeed
        } catch {
            // If it fails, just continue
        }

        // After operations, total deposited = sum of all Put msg.values
        uint256 totalDeposited = deposit1 + deposit2 + 1 ether;
        // Total successfully collected = contract balance decrease
        uint256 totalCollected = contractBalBefore - address(c).balance;
        // Sum of all Acc balances
        uint256 totalAccBalances = c.Acc(alice).balance + c.Acc(bob).balance;

        // Invariant: totalAccBalances + totalCollected == totalDeposited
        assertTrue(totalAccBalances + totalCollected == totalDeposited);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

