pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initDeposit, uint256 reentrantCollect) public {
        // Bind to admissible domain
        vm.assume(initDeposit >= 1 ether);
        vm.assume(reentrantCollect >= 1 ether);
        vm.assume(initDeposit >= reentrantCollect);

        // Deploy reentrant attacker that calls Collect during AddMessage
        Attacker attacker = new Attacker(address(c));
        vm.deal(address(attacker), initDeposit);

        // Attacker makes initial deposit and tries to reenter
        vm.prank(address(attacker));
        attacker.attack{value: initDeposit}(reentrantCollect);

        // Warp past unlock time
        vm.warp(block.timestamp + 1 days);

        // Now try to collect the legitimate remaining balance
        uint256 balanceBefore = c.Acc(address(attacker)).balance;
        uint256 totalCollectedBefore = attacker.totalCollected();

        vm.prank(address(attacker));
        // If balance >= 1 ether and > unlock time, attacker can collect
        try c.Collect(balanceBefore) {
            // Collect succeeded
            uint256 totalCollectedAfter = attacker.totalCollected();
            uint256 balanceAfter = c.Acc(address(attacker)).balance;
            assertTrue(balanceAfter >= totalCollectedAfter - totalCollectedBefore);
        } catch {
            // Collect failed - property holds vacuously
            assertTrue(true);
        }
    }
}

contract Attacker {
    C public target;
    uint256 public totalCollected;

    constructor(address _target) {
        target = C(_target);
    }

    function attack(uint256 _amount) external payable {
        // This will call Put which triggers AddMessage
        target.Put{value: msg.value}(block.timestamp + 365 days);
        totalCollected = 0;
    }

    receive() external payable {
        // Re-enter during Collect's low-level call
        if (msg.sender == address(target)) {
            totalCollected += msg.value;
            // Try to re-enter Put again to trigger another AddMessage
            // which could cause reentrancy
        }
    }

    fallback() external payable {
        if (msg.sender == address(target)) {
            totalCollected += msg.value;
        }
    }
}

