pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint128 unlockTimeArg, uint128 collectAmount) public {
        // Fuzz the unlock time argument (0 to type(uint128).max) and collect amount
        // We need msg.sender to be a distinct actor, but the fuzzer provides raw args.
        // We'll use address(this) as user for simplicity, since we need to prank.
        // The property: If user calls Put with an unlockTimeArg that is strictly less than the current block.timestamp,
        // then any subsequent Collect call before block.timestamp exceeds unlockTime should revert.
        // The mutant allows unlockTime = unlockTimeArg (no block.timestamp floor), so an immediate Collect could succeed.

        // Bound unlockTimeArg to be strictly less than current block.timestamp to model a "past" unlock time argument.
        // We can't exceed current timestamp, but vm.warp can set block.timestamp to some value.
        // Instead, we first warp to a future point, then fuzz unlockTimeArg relative to that.
        // Simpler: use vm.warp to set a known timestamp, then bound unlockTimeArg < that timestamp.
        uint256 currentTime = block.timestamp;
        // Ensure unlockTimeArg is strictly less than currentTime so we are testing a past unlock
        vm.assume(unlockTimeArg < currentTime);
        // Ensure collectAmount is at least MinSum (1 ether) so that Collect can succeed if unlockTime condition fails.
        vm.assume(collectAmount >= 1 ether);
        // We need some Ether to put into the contract to satisfy acc.balance >= collectAmount and >= MinSum
        uint256 depositAmount = collectAmount;
        vm.deal(address(this), depositAmount);

        // Execute Put with the past unlockTimeArg
        vm.prank(address(this));
        c.Put{value: depositAmount}(unlockTimeArg);

        // Now immediately (without advancing time) attempt to Collect. Since unlockTimeArg < currentTime,
        // the unlock time condition block.timestamp > acc.unlockTime should be true (because block.timestamp == currentTime > unlockTimeArg).
        // But the reference contract sets unlockTime = max(_unlockTime, block.timestamp). Since unlockTimeArg < block.timestamp,
        // unlockTime becomes block.timestamp. Then block.timestamp > block.timestamp is false, so Collect must revert.
        // The mutant sets unlockTime = _unlockTime (past value), so block.timestamp > unlockTime is true, and Collect can succeed.
        bool ok;
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference contract should revert (ok == false), the mutant can succeed (ok == true).
        // Our assertion: ok must be false for the property to hold.
        assertTrue(!ok);
    }
}

