import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint128 _unlockTime, uint128 putAmount, uint128 collectAmount) public {
        // Admissible domain: non-zero put and positive collect up to balance, unlockTime unrestricted for fuzz
        vm.assume(putAmount > 0);
        vm.assume(collectAmount > 0);
        vm.assume(collectAmount <= putAmount);

        // Setup caller
        address caller = address(0x1000);
        vm.deal(caller, putAmount);
        vm.prank(caller);

        // Record block.timestamp before Put
        uint256 tsBefore = block.timestamp;
        c.Put{value: putAmount}(_unlockTime);

        // Condition: if the caller's unlockTime is < tsBefore (i.e. strictly past),
        // Collect must revert because block.timestamp == tsBefore < unlockTime is impossible
        // (block.timestamp can only increase, so block.timestamp > unlockTime cannot yet hold).
        // The reference enforces unlockTime >= tsBefore, so this branch is never entered.
        // The mutant may set unlockTime < tsBefore, making an immediate Collect attempt possible.
        uint256 actualUnlock = c.Acc(caller).unlockTime;
        vm.assume(actualUnlock < tsBefore);

        // Now advance time slightly so that block.timestamp > actualUnlock, enabling Collect on mutant
        // but the reference would never allow this combination (unlockTime would have been >= tsBefore).
        vm.warp(tsBefore + 1);

        // Attempt Collect: on reference it should revert because unlockTime was set >= tsBefore
        // and block.timestamp is still < that value (tsBefore+1 < tsBefore <= unlockTime impossible on ref).
        // On mutant, unlockTime < tsBefore < tsBefore+1, so block.timestamp > unlockTime -> Collect allowed.
        vm.prank(caller);
        (bool ok,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Assert: Collect must revert (property: unlock time must protect funds until block.timestamp > unlockTime,
        // and the reference ensures unlockTime >= tsBefore, making immediate Collect impossible).
        // The mutant breaks this by allowing unlockTime < tsBefore and then Collect succeeds.
        assertTrue(!ok, "Collect should revert when unlock time is in the past relative to block.timestamp");
    }
}

