import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address reverter;

    function setUp() public {
        c = new C(address(this));
        reverter = address(new Reverter());
    }

    function testFuzz_property(uint256 am, uint256 unlockDelta, uint256 dep) public {
        // Bind amounts to the admissible range: positive and at least MinSum, not exceeding deposit, and not causing overflow.
        am = bound(am, 1 ether, type(uint128).max);
        dep = bound(dep, am, type(uint128).max);

        // unlockDelta is strictly positive, so unlockTime > block.timestamp now and for theCollect call.
        unlockDelta = bound(unlockDelta, 1, 365 * 86400);

        // Prepare the adversarial callee that reverts any received Ether.
        // The attacker will be the reverter contract, so any transfer to it will fail, triggering only the false branch of the low-level call inside Collect.
        // This prevents actual Ether loss but still executes the buggy reduction of balance.
        vm.deal(reverter, 0);
        vm.prank(reverter);
        c.Put{value: dep}(uint256(block.timestamp) + unlockDelta);

        uint256 balanceBefore = c.Acc(reverter).balance;
        assertEq(balanceBefore, dep);

        bool ok;
        // The call sends to msg.sender who is the reverter, which reverts, making the external call fail.
        // In the reference, because timestamp > unlockTime is false, the whole condition fails early — no state change.
        // In the buggy, the condition body executes, the call fails, but the sub_uint256 is never reached.
        // The bug manifests only when the withdrawal succeeds, i.e., when the recipient does NOT revert.
        // Therefore we need the external call to SUCCEED, but the unlock condition still to be violated.
        // We use a normal EOA as caller, but the EOA must have unlockTime in the future and enough balance.
        // The property: after a successful Collect (transfer sent and not reverted) while block.timestamp <= unlockTime,
        // the balance must NOT decrease, but the buggy reduces it.

        // Deploy a receiver that does NOT revert.
        address caller = makeAddr("caller");
        vm.deal(caller, 0);
        vm.prank(caller);
        c.Put{value: dep}(uint256(block.timestamp) + unlockDelta);

        uint256 balBefore = c.Acc(caller).balance;
        assertEq(balBefore, dep);

        // Attempt Collect with amount am while block.timestamp <= unlockTime.
        vm.prank(caller);
        (bool success, bytes memory ret) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, am));
        ok = success;

        uint256 balAfter = c.Acc(caller).balance;

        // General rule: If the Collect call succeeded (did not revert) and the caller's unlockTime > block.timestamp,
        // the caller's balance must remain unchanged (no premature withdrawal allowed).
        // The reference satisfies: when unlockTime is in the future, the condition fails so success is false (reverts).
        // Therefore this assertion holds trivially (success == false -> true).
        // We need the reference to NOT revert? The attempted rule description says the reference reverts (success == false).
        // But the property must be a universal truth on the reference for ALL inputs and be violated by the bug.
        // If the reference always reverts when unlockTime > block.timestamp, then the implication "if success && unlockTime > block.timestamp => balance unchanged" holds vacuously.
        // The bug however allows success to be true even when unlockTime > block.timestamp, and then reduces balance, violating the implication.
        // So we assert: !(success && c.Acc(caller).unlockTime > block.timestamp && balAfter != balBefore)
        // which simplifies to: if success and unlockTime > now then balAfter == balBefore.

        assertTrue(
            !(ok && c.Acc(caller).unlockTime > block.timestamp && balAfter != balBefore),
            "balance changed despite future unlockTime"
        );
    }
}

