pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        // Restrict to admissible domain: actor != address(this) to avoid self-call issues,
        // and amounts that avoid overflow in setup.
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        depositAmount = bound(depositAmount, 1, type(uint256).max / 2);
        withdrawAmount = bound(withdrawAmount, 1, type(uint256).max / 2);

        // Prepare actor with enough ETH for deposit and gas.
        vm.deal(actor, depositAmount + 10 ether);
        vm.prank(actor);
        c.Put{value: depositAmount}(block.timestamp);

        // Record actor's balance and contract's ETH before Collect.
        (uint unlockTime, uint userBal) = c.Acc(actor);
        uint contractEthBefore = address(c).balance;

        // Perform Collect as actor; we do not force success – the fuzzer explores both paths.
        vm.prank(actor);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", withdrawAmount));

        // Post-state.
        ( , uint userBalAfter) = c.Acc(actor);
        uint contractEthAfter = address(c).balance;

        if (success) {
            // Invariant: if Collect succeeded, the amount transferred (contract ETH decrease)
            // must not exceed the user's pre-balance. The reference enforces this via
            // acc.balance >= _am; the bug omits it and can transfer more.
            uint transferred = contractEthBefore - contractEthAfter;
            assertTrue(transferred <= userBal);
        } else {
            // If Collect reverted, the invariant is vacuously true for this path.
            assertTrue(true);
        }
    }
}

