contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;

    function setUp() public {
        attacker = new ReentrantAttacker();
        // constructor expects a log address; we pass the attacker contract itself as a non-functional log just for deployment
        c = new C(address(attacker));
        // fund the victim with exactly 2 ether (minimum for MinSum check), but the exact amount is fuzzed in test
        vm.deal(address(c), 0);
    }

    function testFuzz_property(uint256 initialBalance, uint256 collectAmount, uint256 unlockTime) public {
        // Keep the domain wide: initialBalance >= 1 ether (MinSum), collectAmount <= initialBalance, unlockTime in past
        uint256 minSum = c.MinSum();
        vm.assume(initialBalance >= minSum && initialBalance <= 1_000_000 ether);
        vm.assume(collectAmount <= initialBalance && collectAmount > 0);
        vm.assume(unlockTime < block.timestamp);

        // Deploy a fresh attacker for each fuzz run to have clean state
        attacker = new ReentrantAttacker();
        c = new C(address(attacker));

        // Setup the attacker account in the victim's storage
        // attacker's balance will be initialBalance, unlockTime will be a past timestamp
        vm.deal(address(attacker), 1_000_000 ether);

        // First, give the attacker a balance in C by calling Put
        vm.prank(address(attacker));
        c.Put{value: initialBalance}(unlockTime);

        // Record the balance before attacking
        uint256 balanceBefore = c.Acc(address(attacker)).balance;

        // The attacker's fallback will re-enter Collect during the low-level call
        attacker.attack(address(c), collectAmount);

        // After the attack, the attacker's balance in C should be balanceBefore - collectAmount
        // (because the reference contract prevents re-entrancy; the mutant allows it and steals more)
        uint256 balanceAfter = c.Acc(address(attacker)).balance;

        // General rule: in the reference, balanceAfter == balanceBefore - collectAmount.
        // In the buggy version, re-entrancy drains extra, so balanceAfter < balanceBefore - collectAmount.
        // We assert that balanceAfter <= balanceBefore - collectAmount (true for reference, but the bug will sometimes make it strictly smaller).
        assertTrue(balanceAfter <= balanceBefore - collectAmount);
    }
}

contract ReentrantAttacker {
    C target;
    uint256 amountToSteal;
    bool attacking;

    function attack(address _target, uint256 _amount) external {
        target = C(payable(_target));
        amountToSteal = _amount;
        attacking = true;
        target.Collect(amountToSteal);
        attacking = false;
    }

    fallback() external payable {
        if (attacking && address(target).balance >= amountToSteal) {
            attacking = false;
            target.Collect(amountToSteal);
            attacking = true;
        }
    }
}

